// ===== Camada da API: só rede =====
const ApiService = {
  URL_BASE: "https://jsonplaceholder.typicode.com/todos",

  async requisitar(url, opcoes = {}) {
    const resposta = await fetch(url, opcoes);
    if (!resposta.ok) throw new Error(`Status ${resposta.status}`);
    return resposta.status === 204 ? null : resposta.json();
  },

  listar() {
    return this.requisitar(`${this.URL_BASE}?_limit=5`);
  },

  criar(tarefa) {
    return this.requisitar(this.URL_BASE, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(tarefa)
    });
  },

  atualizar(tarefa) {
    return this.requisitar(`${this.URL_BASE}/${tarefa.id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(tarefa)
    });
  },

  deletar(id) {
    return this.requisitar(`${this.URL_BASE}/${id}`, { method: "DELETE" });
  }
};

// ===== Camada da interface: só DOM =====
const lista = document.getElementById("lista-tarefas");
const campo = document.getElementById("nova-tarefa");
const statusMsg = document.getElementById("status-msg");

function criarItem(tarefa) {
  const li = document.createElement("li");
  li.id = `tarefa-${tarefa.id}`;

  const texto = document.createElement("span");
  texto.textContent = tarefa.title;
  if (tarefa.completed) texto.classList.add("concluida");

  const botaoConcluir = document.createElement("button");
  botaoConcluir.textContent = "Concluir";
  botaoConcluir.addEventListener("click", () => concluir(tarefa, texto));

  const botaoExcluir = document.createElement("button");
  botaoExcluir.textContent = "Excluir";
  botaoExcluir.addEventListener("click", () => excluir(tarefa.id));

  li.append(texto, botaoConcluir, botaoExcluir);
  return li;
}

async function carregar() {
  try {
    const tarefas = await ApiService.listar();
    lista.innerHTML = "";
    tarefas.forEach(t => lista.appendChild(criarItem(t)));
  } catch (erro) {
    statusMsg.textContent = "Não foi possível carregar as tarefas.";
  }
}

async function adicionar() {
  const titulo = campo.value.trim();
  if (!titulo) return;
  try {
    const criada = await ApiService.criar({ title: titulo, completed: false, userId: 1 });
    lista.prepend(criarItem(criada));
    campo.value = "";
    statusMsg.textContent = `Tarefa criada com ID ${criada.id}.`;
  } catch (erro) {
    statusMsg.textContent = "Erro ao criar a tarefa.";
  }
}

async function concluir(tarefa, elementoTexto) {
  try {
    const atualizada = await ApiService.atualizar({ ...tarefa, completed: true });
    if (atualizada.completed) elementoTexto.classList.add("concluida");
  } catch (erro) {
    statusMsg.textContent = "Erro ao concluir a tarefa.";
  }
}

async function excluir(id) {
  try {
    await ApiService.deletar(id);
    document.getElementById(`tarefa-${id}`).remove();
  } catch (erro) {
    statusMsg.textContent = "Erro ao excluir a tarefa.";
  }
}

document.getElementById("botao-adicionar").addEventListener("click", adicionar);
carregar();

