const PostService = {
  url: `${BASE}/posts`,
  config(metodo, dados) {
    return {
      method: metodo,
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(dados)
    };
  },
  async listar() {
    const r = await fetch(`${this.url}?_limit=3`);
    return r.json();
  },
  async criar(dados) {
    const r = await fetch(this.url, this.config("POST", dados));
    return r.json();
  },
  async atualizar(id, dados) {
    const r = await fetch(`${this.url}/${id}`, this.config("PUT", { id, ...dados }));
    return r.json();
  },
  async deletar(id) {
    const r = await fetch(`${this.url}/${id}`, { method: "DELETE" });
    return r.ok;
  }
};

