const campo = document.getElementById("titulo");
const lista = document.getElementById("posts");

async function publicar() {
  try {
    const r = await fetch(`${BASE}/posts`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: campo.value, body: "", userId: 1 })
    });
    if (!r.ok) throw new Error(r.status);
    const post = await r.json();

    const li = document.createElement("li");
    li.textContent = post.title;
    const botao = document.createElement("button");
    botao.textContent = "Excluir";
    botao.addEventListener("click", () => excluir(post.id, li));
    li.appendChild(botao);
    lista.appendChild(li);
    campo.value = "";
  } catch (e) {
    alert("Erro ao publicar.");
  }
}

async function excluir(id, li) {
  try {
    const r = await fetch(`${BASE}/posts/${id}`, { method: "DELETE" });
    if (!r.ok) throw new Error(r.status);
    li.remove(); // só depois da confirmação
  } catch (e) {
    alert("Erro ao excluir.");
  }
}

document.getElementById("publicar").addEventListener("click", publicar);

